{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or REPLACE TABLE SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS AS Select * from ( With final as (Select * from ( Select * from ( With overall as ( Select CASE WHEN POSITION(\'-\' IN \"BARCODE\") > 0 AND LEFT(\"BARCODE\", 2) = \'SH\' THEN SPLIT_PART(\"BARCODE\", \'-\', 1) WHEN POSITION(\'-\' IN \"BARCODE\") > 0 THEN SPLIT_PART(\"BARCODE\", \'-\', 1) || \'-\' || SPLIT_PART(\"BARCODE\", \'-\', 2) ELSE \"BARCODE\" END AS sku_group, \"BARCODE\" AS \"ITEM CODE\", branch_code_priority , \"BRANCH NAME\", CASE WHEN \"RECEIPT DATE\" LIKE \'%/%/%\' THEN TO_DATE(\"RECEIPT DATE\", \'DD/MM/YYYY\') WHEN \"RECEIPT DATE\" LIKE \'%-%-%\' THEN TO_DATE(\"RECEIPT DATE\", \'DD-MM-YYYY\') ELSE NULL END AS Inward_date, SUM(\"PUR QTY\") AS qty, \'PUV Verification Pending\' as Status, DATEDIFF( DAY, inward_date, CURRENT_DATE ) AS aging from ( SELECT a.*, b.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification a left join ( SELECT DISTINCT e.\"BRANCH NAME\", s.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification e LEFT JOIN snitch_db.maplemonk.storepriority s ON e.\"BRANCH NAME\" LIKE \'%\' || s.branch_name_priority || \'%\') b on a.\"BRANCH NAME\" =b.\"BRANCH NAME\" where lower(\"GOODS IN TRANSIT\") = \'true\') GROUP BY 1,2,3,4,5 Union ALL Select case WHEN POSITION(\'-\' IN SKU) > 0 AND LEFT(SKU, 2) = \'SH\' THEN SPLIT_PART(SKU, \'-\', 1) WHEN POSITION(\'-\' IN SKU) > 0 THEN SPLIT_PART(SKU, \'-\', 1) || \'-\' || SPLIT_PART(SKU, \'-\', 2) ELSE SKU END as sku_group ,* from ( with git as (select final_store::TEXT as FINAL_STORE, order_date, sku, final_status , sum(qty) as q1 from snitch_db.maplemonk.b2b_journey where final_status not in (\'INWARDED\') group by 1,2,3,4 ), branch as (select store_name::TEXT as STORE_NAME , store_code from snitch_db.maplemonk.OFFLINE_STORE_DETAILED_MAPPING) select g.sku, b.store_code as branch_code, g.final_store as store, g.order_date ,g.q1 as qty , g.final_status as status, current_date - g.order_date as aging from git g left join branch b on g.final_store::TEXT = b.store_name ) ) , deatilas as ( select * from ( select CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END as sku_group, product_name, category, final_ros, natural_ros, sku_class , ROW_NUMBER() OVER (PARTITION BY CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END ORDER BY 1) AS rn, from snitch_db.maplemonk.availability_master_v2) where rn=1 ) SELECT a.*, b.product_name, b.category, b.final_ros AS online_final_ros, b.natural_ros AS online_natural_ros, b.sku_class FROM overall a LEFT JOIN deatilas b ON a.SKU_GROUP = b.sku_group ) where sku_group not like \'%CB%\' ) ), haa as ( Select * from ( SELECT DISTINCT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY order_date DESC) AS rn FROM snitch_db.maplemonk.STORE_fact_items_offline) WHERE rn = 1 ) Select a.SKU_GROUP, a.\"ITEM CODE\", a.INWARD_DATE, a.QTY, a.STATUS, a.AGING, a.PRODUCT_NAME, a.CATEGORY, a.ONLINE_FINAL_ROS, a.ONLINE_NATURAL_ROS, a.SKU_CLASS, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN 28 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN 40 WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN 42 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNKW\' THEN 48 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNOW\' THEN 48 ELSE COALESCE(b.branch_code, a.branch_code_priority) END AS branch_code, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN \'SNITCH - COFO - METRO MALL\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNKW\' THEN \'SNITCH - FOCO - PALASSIO MALL\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNOW\' THEN \'SNITCH - FOCO - PALASSIO MALL\' ELSE COALESCE(b.marketplace_mapped, a.\"BRANCH NAME\") END AS Store from final a left join haa b on a.branch_code_priority = b.branch_code ) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
